        const pendingUrlEl = document.getElementById('m3u-url-input');
        const pendingNameEl = document.getElementById('m3u-source-name-input');
        if (pendingUrlEl && pendingUrlEl.value.trim()) {
          const typedUrl = pendingUrlEl.value.trim();
